-- Тема 12: варианты ответов выровнены по длине и форме (49 исправлений в 13 вопросах), ключи не меняются.
-- Источник: scripts/questions/084_option_length_topic12.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'За ходом какой команды позволяет следить представление pg_stat_progress_vacuum?', 'VACUUM, включая процессы автоочистки', 'VACUUM, включая автоочистку', 'Обычный VACUUM и автоочистка.', 'Обычный VACUUM и процессы автоочистки.'),
        ('option', 'За ходом какой команды позволяет следить представление pg_stat_progress_vacuum?', 'ANALYZE', 'ANALYZE и обновление статистики', 'Для ANALYZE — pg_stat_progress_analyze.', NULL),
        ('option', 'За ходом какой команды позволяет следить представление pg_stat_progress_vacuum?', 'CREATE INDEX', 'CREATE INDEX и REINDEX', 'Для CREATE INDEX — pg_stat_progress_create_index.', 'Для CREATE INDEX и REINDEX — pg_stat_progress_create_index.'),
        ('option', 'За ходом какой команды позволяет следить представление pg_stat_progress_vacuum?', 'COPY', 'COPY и импорт данных', 'Для COPY — pg_stat_progress_copy.', NULL),
        ('option', 'Какое расширение собирает статистику по выполняемым запросам?', 'pgstattuple', 'Расширение pgstattuple', 'Статистика по версиям строк и свободному месту.', NULL),
        ('option', 'Какое расширение собирает статистику по выполняемым запросам?', 'pg_buffercache', 'Расширение pg_buffercache', 'Показывает содержимое буферного кеша.', NULL),
        ('option', 'Какое расширение собирает статистику по выполняемым запросам?', 'pg_wait_sampling', 'Расширение pg_wait_sampling', 'Стороннее расширение, собирает статистику ожиданий.', NULL),
        ('option', 'Какое расширение собирает статистику по выполняемым запросам?', 'pg_stat_statements', 'Расширение pg_stat_statements', 'Число вызовов, время, строки для каждого запроса.', NULL),
        ('option', 'Какой параметр включает коллектор сообщений?', 'log_destination', 'Параметр log_destination', 'Задаёт приёмники журнала.', NULL),
        ('option', 'Какой параметр включает коллектор сообщений?', 'logging_collector', 'Параметр logging_collector', 'Включает отдельный процесс, который пишет журнал в файлы.', NULL),
        ('option', 'Какой параметр включает коллектор сообщений?', 'log_statement', 'Параметр log_statement', 'Записывает тексты команд.', NULL),
        ('option', 'Какой параметр включает коллектор сообщений?', 'log_min_messages', 'Параметр log_min_messages', 'Минимальный уровень записываемых сообщений.', NULL),
        ('option', 'Что нужно, чтобы использовать приёмники журнала csvlog и jsonlog?', 'Включённый коллектор сообщений', 'Включённый коллектор сообщений сервера', 'Эти форматы пишет только коллектор.', NULL),
        ('option', 'Что нужно, чтобы использовать приёмники журнала csvlog и jsonlog?', 'Демон syslog', 'Работающий демон syslog', 'syslog — отдельный приёмник.', NULL),
        ('option', 'Что нужно, чтобы использовать приёмники журнала csvlog и jsonlog?', 'ОС Windows', 'Сервер под управлением Windows', 'Операционная система роли не играет.', NULL),
        ('option', 'Что нужно, чтобы использовать приёмники журнала csvlog и jsonlog?', 'Утилита pgBadger', 'Установленную утилиту pgBadger', 'pgBadger анализирует журнал, для записи он не нужен.', NULL),
        ('option', 'Какой параметр записывает в журнал команды, выполнявшиеся дольше заданного времени?', 'log_duration', 'log_duration — время всех команд', 'Записывает время всех команд.', NULL),
        ('option', 'Какой параметр записывает в журнал команды, выполнявшиеся дольше заданного времени?', 'log_statement', 'log_statement — тексты команд', 'Записывает текст команд выбранных типов.', NULL),
        ('option', 'Какой параметр записывает в журнал команды, выполнявшиеся дольше заданного времени?', 'log_min_duration_statement', 'log_min_duration_statement — долгие команды', 'Записывает команды не короче порога; 0 — все, -1 — отключено.', NULL),
        ('option', 'Какой параметр записывает в журнал команды, выполнявшиеся дольше заданного времени?', 'log_lock_waits', 'log_lock_waits — долгие ожидания блокировок', 'Записывает долгие ожидания блокировок.', NULL),
        ('option', 'Как часто обслуживающий процесс записывает собранную статистику в разделяемую память?', 'Не чаще одного раза в секунду', 'Не чаще раза в секунду', 'Интервал задан при компиляции.', NULL),
        ('option', 'Как часто обслуживающий процесс записывает собранную статистику в разделяемую память?', 'После каждого запроса', 'После выполнения каждого запроса', 'Это было бы слишком накладно.', NULL),
        ('option', 'Как часто обслуживающий процесс записывает собранную статистику в разделяемую память?', 'Только при остановке сервера', 'При остановке сервера', 'При остановке статистика сохраняется на диск.', 'Статистика сохраняется на диск при остановке, но обслуживающий процесс записывает её в разделяемую память гораздо чаще.'),
        ('option', 'Как часто обслуживающий процесс записывает собранную статистику в разделяемую память?', 'Только при контрольной точке', 'При каждой контрольной точке', 'Контрольная точка к статистике не относится.', NULL),
        ('option', 'Что делает значение stats_fetch_consistency = snapshot?', 'Кеширует статистику только по одному объекту', 'Кеширует статистику по одному объекту', 'Так не делает ни одно значение; при cache, используемом по умолчанию, статистика кешируется отдельно для каждого объекта при первом обращении.', NULL),
        ('option', 'Что делает значение stats_fetch_consistency = snapshot?', 'Кеширует всю статистику текущей базы до конца транзакции', 'Кеширует статистику базы до конца транзакции', 'Даёт самую согласованную картину ценой затрат на кеширование.', NULL),
        ('option', 'Как сбросить закешированную в процессе статистику раньше конца транзакции?', 'Выполнить ANALYZE', 'Выполнить команду ANALYZE в сеансе', 'ANALYZE собирает статистику для планировщика, а не сбрасывает кеш накопительной статистики.', NULL),
        ('option', 'Как сбросить закешированную в процессе статистику раньше конца транзакции?', 'Вызвать pg_reload_conf()', 'Вызвать функцию pg_reload_conf() сервера', 'Эта функция перечитывает конфигурацию.', NULL),
        ('option', 'Как сбросить закешированную в процессе статистику раньше конца транзакции?', 'Вызвать pg_stat_reset()', 'Вызвать функцию pg_stat_reset()', 'Эта функция обнуляет счётчики статистики базы, а не кеш процесса.', NULL),
        ('option', 'Как сбросить закешированную в процессе статистику раньше конца транзакции?', 'Вызвать pg_stat_clear_snapshot()', 'Вызвать функцию pg_stat_clear_snapshot()', 'После этого статистика будет прочитана заново.', NULL),
        ('option', 'Что верно для коллектора сообщений?', 'Он включён по умолчанию', 'Он включён по умолчанию при установке', 'По умолчанию logging_collector = off.', NULL),
        ('option', 'Что верно для коллектора сообщений?', 'При большой нагрузке он может стать узким местом', 'При нагрузке он может стать узким местом', 'Это следствие того, что он не теряет сообщения.', NULL),
        ('option', 'Что верно для коллектора сообщений?', 'Он никогда не теряет сообщения', 'Он не теряет сообщения при нагрузке', 'В отличие от syslog.', 'В отличие от syslog, коллектор не теряет сообщения.'),
        ('option', 'Что верно для коллектора сообщений?', 'Он работает только с приёмником syslog', 'Он работает с приёмником syslog', 'Он записывает в файлы stderr, csvlog и jsonlog.', 'Он записывает в файлы stderr, csvlog и jsonlog, а не в syslog.'),
        ('option', 'Коллектор сообщений включён, журнал пишется в одном формате (log_destination = ''stderr''). Сколько файлов журнала сообщений получится при log_filename = ''postgresql-%a.log'', ротации раз в сутки и log_truncate_on_rotation = on?', 'Семь — по дням недели', 'Семь файлов по дням недели', 'Через неделю файлы начнут перезаписываться.', NULL),
        ('option', 'Коллектор сообщений включён, журнал пишется в одном формате (log_destination = ''stderr''). Сколько файлов журнала сообщений получится при log_filename = ''postgresql-%a.log'', ротации раз в сутки и log_truncate_on_rotation = on?', 'Тридцать один', 'Тридцать один файл', 'Так было бы с маской дня месяца %d.', NULL),
        ('option', 'Коллектор сообщений включён, журнал пишется в одном формате (log_destination = ''stderr''). Сколько файлов журнала сообщений получится при log_filename = ''postgresql-%a.log'', ротации раз в сутки и log_truncate_on_rotation = on?', 'Один', 'Один постоянный файл', 'Имя файла меняется каждый день недели.', NULL),
        ('option', 'Коллектор сообщений включён, журнал пишется в одном формате (log_destination = ''stderr''). Сколько файлов журнала сообщений получится при log_filename = ''postgresql-%a.log'', ротации раз в сутки и log_truncate_on_rotation = on?', 'Двадцать четыре', 'Двадцать четыре файла в сутки', 'Так будет с маской %H и ротацией раз в час.', NULL),
        ('option', 'Что делает параметр log_truncate_on_rotation = on?', 'При ротации по времени перезаписывает уже существующий файл с тем же именем', 'Перезаписывает файл с тем же именем при ротации', 'Иначе новые сообщения дописывались бы в конец старого файла.', 'При ротации по времени перезаписывает уже существующий файл с тем же именем; иначе новые сообщения дописывались бы в конец старого файла.'),
        ('option', 'Что делает параметр log_truncate_on_rotation = on?', 'Удаляет все старые файлы журнала', 'Удаляет старые файлы журнала при ротации', 'Удаления нет: перезаписывается только файл с тем же именем.', NULL),
        ('option', 'Что делает параметр log_truncate_on_rotation = on?', 'Сжимает старые файлы', 'Сжимает старые файлы журнала при ротации', 'Сжатия коллектор не выполняет.', NULL),
        ('option', 'Что делает параметр log_truncate_on_rotation = on?', 'Отключает ротацию', 'Отключает ротацию файлов журнала', 'Наоборот, имеет смысл только вместе с ротацией.', NULL),
        ('option', 'Какое ограничение есть у анализатора журналов pgBadger?', 'Он работает только в Windows', 'Он запускается на Windows, но не на Linux', 'Такого ограничения нет.', 'Такого ограничения нет: pgBadger написан на Perl и работает на разных ОС.'),
        ('option', 'Какое ограничение есть у анализатора журналов pgBadger?', 'Он требует расширения pg_stat_statements', 'Он требует расширения pg_stat_statements для работы', 'pgBadger анализирует журнал сообщений.', NULL),
        ('option', 'Какое ограничение есть у анализатора журналов pgBadger?', 'Он работает только с базами до 1 ГБ', 'Он обрабатывает журналы баз до 1 ГБ', 'Такого ограничения нет.', 'Такого ограничения нет: размер базы не важен.'),
        ('option', 'Какое ограничение есть у анализатора журналов pgBadger?', 'Он требует определённых настроек журнала, в частности сообщений на английском', 'Он требует настроек журнала и английских сообщений', 'Об этом нужно помнить, настраивая журнал.', 'Об этом нужно помнить, настраивая журнал: pgBadger разбирает определённый формат сообщений, поэтому нужны настройки журнала и сообщения на английском.'),
        ('option', 'Можно ли средствами PostgreSQL ограничить роли объём занимаемого на диске места?', 'Нет: квоты задаются средствами ОС для пользователя ОС, под которым работает сервер', 'Нет: квоты задаются средствами ОС для сервера', 'Квота для этого пользователя должна быть достаточной.', 'Квоты задаются средствами ОС для пользователя ОС, под которым работает сервер; квота для этого пользователя должна быть достаточной.'),
        ('option', 'Можно ли средствами PostgreSQL ограничить роли объём занимаемого на диске места?', 'Да, параметром work_mem', 'Да, параметром work_mem для роли', 'work_mem ограничивает память для операций, а не место на диске.', NULL),
        ('option', 'Можно ли средствами PostgreSQL ограничить роли объём занимаемого на диске места?', 'Да, через табличные пространства', 'Да, через табличные пространства сервера', 'Табличные пространства определяют размещение данных, а не квоты.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
